package com.catastrophic.events;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("catastrophicevents")
public interface CatastrophicEventsConfig extends Config
{
	@ConfigItem(
		position = 1,
		keyName = "token",
		name = "Plugin token",
		description = "Paste the token DM'd to you by the /link-plugin command in Discord.",
		secret = true
	)
	default String token()
	{
		return "";
	}

	@ConfigItem(
		position = 2,
		keyName = "lootSharingEnabled",
		name = "Share big loot drops",
		description = "Post a screenshot and summary to Discord when you receive a non-stacked drop worth 1.5m gp or more."
	)
	default boolean lootSharingEnabled()
	{
		return false;
	}

	@ConfigItem(
		position = 3,
		keyName = "deathScreenshotsEnabled",
		name = "Share death screenshots",
		description = "Post a screenshot to Discord whenever you die."
	)
	default boolean deathScreenshotsEnabled()
	{
		return false;
	}

	@ConfigItem(
		position = 4,
		keyName = "deathMessage",
		name = "Death message",
		description = "Text posted alongside death alerts. Use $name for your character's name, e.g. \"$name is trying his best\". Leave blank for the default \"Died.\""
	)
	default String deathMessage()
	{
		return "$name Died.";
	}

	@ConfigItem(
		position = 5,
		keyName = "eventRemindersEnabled",
		name = "Event chat reminders",
		description = "Show private chatbox messages for events you're signed up for: milestone reminders (T-3h/T-1h/T-5min) and a once-per-session summary. Only visible to you - nothing is posted anywhere."
	)
	default boolean eventRemindersEnabled()
	{
		return false;
	}

	@ConfigItem(
		position = 6,
		keyName = "accomplishmentSharingEnabled",
		name = "Share account accomplishments",
		description = "Post to Discord when you hit a skill/XP/total level milestone, complete a Grandmaster or special quest, receive a mega-rare drop, or achieve certain first-time capes."
	)
	default boolean accomplishmentSharingEnabled()
	{
		return false;
	}

	@ConfigItem(
		position = 7,
		keyName = "petDropSharingEnabled",
		name = "Share pet drops",
		description = "Post to Discord when you receive a pet."
	)
	default boolean petDropSharingEnabled()
	{
		return false;
	}
}

package com.catastrophic.events.alerts;

import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;

/** Captures the current client frame as PNG bytes, for attaching to Discord alerts. */
@Slf4j
public class ScreenshotCapture
{
	private final DrawManager drawManager;

	@Inject
	public ScreenshotCapture(DrawManager drawManager)
	{
		this.drawManager = drawManager;
	}

	public void capture(Consumer<byte[]> onCaptured)
	{
		drawManager.requestNextFrameListener(image ->
		{
			BufferedImage bufferedImage = ImageUtil.bufferedImageFromImage(image);
			try (ByteArrayOutputStream out = new ByteArrayOutputStream())
			{
				ImageIO.write(bufferedImage, "png", out);
				onCaptured.accept(out.toByteArray());
			}
			catch (IOException e)
			{
				log.debug("Failed to encode alert screenshot", e);
			}
		});
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.google.common.base.Strings;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;

/**
 * Shares first-time PvM/skilling rewards to Discord: fire cape, infernal cape, Dizana's quiver.
 * Deliberately not named "achievement cape" - that's ambiguous with the actual Achievement Diary
 * cape, which is excluded from this feature (see PLAN.md). Each reward is gated by a one-time
 * per-profile flag so it can never re-fire. Filtered to ChatMessageType.GAMEMESSAGE so a player
 * can't spoof an alert by typing matching text themselves (same fix applied to PetDropListener
 * after a real spoofing incident).
 */
@Slf4j
public class OneTimeRewardListener
{
	private static final String CONFIG_GROUP = "catastrophicevents";

	// Matched on distinctive keyword pairs rather than an exact sentence, since precise in-game
	// wording wasn't verified against a live client - see PLAN.md "Concerns to watch".
	private static final Pattern FIRE_CAPE_TOPIC = Pattern.compile("fight cave", Pattern.CASE_INSENSITIVE);
	private static final Pattern INFERNAL_CAPE_TOPIC = Pattern.compile("inferno", Pattern.CASE_INSENSITIVE);
	private static final Pattern DIZANAS_QUIVER_TOPIC = Pattern.compile("dizana", Pattern.CASE_INSENSITIVE);
	private static final Pattern COMPLETION_VERB = Pattern.compile("complet|obtain|congratulat", Pattern.CASE_INSENSITIVE);

	private final CatastrophicEventsConfig config;
	private final ConfigManager configManager;
	private final AlertsApiClient alertsApiClient;

	@Inject
	public OneTimeRewardListener(CatastrophicEventsConfig config, ConfigManager configManager, AlertsApiClient alertsApiClient)
	{
		this.config = config;
		this.configManager = configManager;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.accomplishmentSharingEnabled())
		{
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();
		if (Strings.isNullOrEmpty(message) || !COMPLETION_VERB.matcher(message).find())
		{
			return;
		}

		if (FIRE_CAPE_TOPIC.matcher(message).find())
		{
			fireOnce("firstFireCapeAlertSent", "Fire Cape", "achieved their first Fire cape");
		}
		else if (INFERNAL_CAPE_TOPIC.matcher(message).find())
		{
			fireOnce("firstInfernalCapeAlertSent", "Infernal Cape", "achieved their first Infernal cape");
		}
		else if (DIZANAS_QUIVER_TOPIC.matcher(message).find())
		{
			fireOnce("firstDizanasQuiverAlertSent", "Dizana's Quiver", "achieved their first Dizana's quiver");
		}
	}

	// Flag is set before the send completes (not in onSuccess) so two chat lines about the same
	// achievement arriving close together can't both slip past the check - same dedupe-first
	// tradeoff CofferAlertListener/catabot's coffer dedup already makes elsewhere in this codebase.
	private void fireOnce(String flagKey, String title, String summary)
	{
		if (!Strings.isNullOrEmpty(configManager.getConfiguration(CONFIG_GROUP, flagKey)))
		{
			return;
		}

		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		configManager.setConfiguration(CONFIG_GROUP, flagKey, "true");

		alertsApiClient.sendAlert(token, AlertKind.ACCOMPLISHMENT, summary, title, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				log.debug("One-time reward alert failed: {}", message);
			}
		});
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.google.common.base.Strings;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

/** Shares pet drops to Discord with a screenshot. */
@Slf4j
public class PetDropListener
{
	// Covers the known pet-obtained message families: "You have a funny feeling like you're being
	// followed." (combat/boss/minigame pets, first time), "You have a funny feeling like you would
	// have been followed." (duplicate pet roll), and "You feel something weird sneaking into your
	// backpack." (skilling pets). Filtered to ChatMessageType.GAMEMESSAGE below so a player can't
	// spoof an alert by typing this text themselves - confirmed against a real Discord incident and
	// verified against the "Discord Notifications" Hub plugin's equivalent check.
	private static final Pattern PET_OBTAINED = Pattern.compile(
		"funny feeling like you're being followed"
			+ "|funny feeling like you would have been followed"
			+ "|feel something weird sneaking into your backpack",
		Pattern.CASE_INSENSITIVE);

	private final CatastrophicEventsConfig config;
	private final ScreenshotCapture screenshotCapture;
	private final AlertsApiClient alertsApiClient;

	@Inject
	public PetDropListener(CatastrophicEventsConfig config, ScreenshotCapture screenshotCapture,
		AlertsApiClient alertsApiClient)
	{
		this.config = config;
		this.screenshotCapture = screenshotCapture;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.petDropSharingEnabled())
		{
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();
		if (Strings.isNullOrEmpty(message) || !PET_OBTAINED.matcher(message).find())
		{
			return;
		}

		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		screenshotCapture.capture(png -> alertsApiClient.sendAlert(token, AlertKind.PET, "received a pet", null, png,
			new ApiCallback<Void>()
			{
				@Override
				public void onSuccess(Void result)
				{
				}

				@Override
				public void onError(ApiErrorType type, String errorMessage)
				{
					log.debug("Pet drop alert failed: {}", errorMessage);
				}
			}));
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.google.common.base.Strings;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ActorDeath;
import net.runelite.client.eventbus.Subscribe;

/** Shares a screenshot to Discord whenever the local player dies. */
@Slf4j
public class DeathAlertListener
{
	/** Placeholder in the configured death message that gets replaced with the player's name. */
	public static final String NAME_TOKEN = "$name";

	private final Client client;
	private final CatastrophicEventsConfig config;
	private final ScreenshotCapture screenshotCapture;
	private final AlertsApiClient alertsApiClient;

	@Inject
	public DeathAlertListener(Client client, CatastrophicEventsConfig config,
		ScreenshotCapture screenshotCapture, AlertsApiClient alertsApiClient)
	{
		this.client = client;
		this.config = config;
		this.screenshotCapture = screenshotCapture;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!config.deathScreenshotsEnabled())
		{
			return;
		}

		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		String rawMessage = Strings.isNullOrEmpty(config.deathMessage()) ? "Died." : config.deathMessage();

		String playerName = client.getLocalPlayer().getName();
		String message = playerName == null ? rawMessage : rawMessage.replace(NAME_TOKEN, playerName);

		screenshotCapture.capture(png -> alertsApiClient.sendAlert(token, AlertKind.DEATH, message, png, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				log.debug("Death alert failed: {}", message);
			}
		}));
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
