/** Shares clan coffer deposit/withdraw chat messages to Discord as text (no screenshot). Always on - no config toggle. */
@Slf4j
public class CofferAlertListener
{
	// e.g. "Zezima has deposited 500,000 coins into the coffer." / "...withdrawn... from the coffer."
	private static final Pattern COFFER_TRANSACTION = Pattern.compile(
		"coffer", Pattern.CASE_INSENSITIVE);
	private static final Pattern COFFER_VERB = Pattern.compile(
		"deposit|withdr", Pattern.CASE_INSENSITIVE);

	private final CatastrophicEventsConfig config;
	private final AlertsApiClient alertsApiClient;

	@Inject
	public CofferAlertListener(CatastrophicEventsConfig config, AlertsApiClient alertsApiClient)
	{
		this.config = config;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.CLAN_MESSAGE)
		{
			return;
		}

		String message = event.getMessage();
		if (Strings.isNullOrEmpty(message)
			|| !COFFER_TRANSACTION.matcher(message).find()
			|| !COFFER_VERB.matcher(message).find())
		{
			return;
		}

		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		alertsApiClient.sendAlert(token, AlertKind.COFFER, message, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
			}

			@Override
			public void onError(ApiErrorType type, String errorMessage)
			{
				log.debug("Coffer alert failed: {}", errorMessage);
			}
		});
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.google.common.base.Strings;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

/**
 * Shares skill/XP/total-level milestones to Discord: 99s, 25m XP-past-99 milestones, 50m total XP
 * milestones, and total level milestones of exactly 1750/2000/2200 (with a screenshot). Entirely
 * chat-message driven - no polling, no client-state baseline of any kind. Each of these messages
 * only ever appears live, the moment the
 * real achievement happens, so unlike the previous Quest.getState()/StatChanged-polling approach
 * (which needed a "what did the player already have coming into this session" baseline that proved
 * impossible to time correctly around login - confirmed live, twice, for both quests and skills) there
 * is nothing to race against and nothing to get wrong.
 */
@Slf4j
public class SkillMilestoneListener
{
	// Only these three total-level thresholds are worth a Discord alert - all other totals
	// (including 2277/max cape) are ignored, per explicit product decision.
	private static final Set<Integer> TRACKED_TOTAL_LEVEL_THRESHOLDS = Set.of(1750, 2000, 2200);

	// Confirmed live against a real client - exact Jagex wording (see task worklog for screenshots).
	private static final Pattern SKILL_LEVEL_UP = Pattern.compile(
		"Congratulations, you've just advanced your (?<skill>[A-Za-z]+) level\\. You are now level (?<level>\\d+)\\.");
	private static final Pattern TOTAL_LEVEL_MILESTONE = Pattern.compile(
		"Congratulations, you've reached a total level of (?<total>[\\d,]+)\\.");

	// Best-effort guess, not confirmed against a live client - same caveat as PetDropListener/
	// OneTimeRewardListener (concerns.json WRN-006). OSRS's native broadcast system may not actually
	// announce round XP numbers at all, unlike level-ups and total level, which are confirmed real; if
	// these never fire, that's the likely reason - tighten the wording or drop the feature once observed
	// live (or not observed after a reasonable amount of play).
	private static final Pattern SKILL_XP_MILESTONE = Pattern.compile(
		"Congratulations, you've reached (?<xp>[\\d,]+) experience in (?<skill>[A-Za-z]+)\\.");
	private static final Pattern TOTAL_XP_MILESTONE = Pattern.compile(
		"Congratulations, you've reached (?<xp>[\\d,]+) total experience\\.");

	private final CatastrophicEventsConfig config;
	private final ScreenshotCapture screenshotCapture;
	private final AlertsApiClient alertsApiClient;

	@Inject
	public SkillMilestoneListener(CatastrophicEventsConfig config, ScreenshotCapture screenshotCapture,
		AlertsApiClient alertsApiClient)
	{
		this.config = config;
		this.screenshotCapture = screenshotCapture;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.accomplishmentSharingEnabled() || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();
		if (Strings.isNullOrEmpty(message))
		{
			return;
		}

		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		Matcher levelUp = SKILL_LEVEL_UP.matcher(message);
		if (levelUp.find())
		{
			handleSkillLevelUp(token, levelUp);
			return;
		}

		Matcher totalLevel = TOTAL_LEVEL_MILESTONE.matcher(message);
		if (totalLevel.find())
		{
			handleTotalLevelMilestone(token, totalLevel);
			return;
		}

		Matcher skillXp = SKILL_XP_MILESTONE.matcher(message);
		if (skillXp.find())
		{
			handleSkillXpMilestone(token, skillXp);
			return;
		}

		Matcher totalXp = TOTAL_XP_MILESTONE.matcher(message);
		if (totalXp.find())
		{
			handleTotalXpMilestone(token, totalXp);
		}
	}

	private void handleSkillLevelUp(String token, Matcher matcher)
	{
		if (Integer.parseInt(matcher.group("level")) != 99)
		{
			return;
		}

		String skillName = matcher.group("skill");
		post(token, String.format("reached 99 %s", skillName), String.format("99 %s", skillName));
	}

	private void handleTotalLevelMilestone(String token, Matcher matcher)
	{
		int total = Integer.parseInt(matcher.group("total").replace(",", ""));
		if (!TRACKED_TOTAL_LEVEL_THRESHOLDS.contains(total))
		{
			return;
		}

		String summary = String.format("reached %,d Total Level", total);
		String title = String.format("%,d Total Level", total);
		screenshotCapture.capture(png -> postWithScreenshot(token, summary, title, png));
	}

	private void handleSkillXpMilestone(String token, Matcher matcher)
	{
		long xp = Long.parseLong(matcher.group("xp").replace(",", ""));
		String skillName = matcher.group("skill");
		post(token, String.format("reached %,d XP in %s", xp, skillName), String.format("%s XP milestone", skillName));
	}

	private void handleTotalXpMilestone(String token, Matcher matcher)
	{
		long xp = Long.parseLong(matcher.group("xp").replace(",", ""));
		post(token, String.format("reached %,d Total XP", xp), "Total XP milestone");
	}

	private void postWithScreenshot(String token, String summary, String title, byte[] png)
	{
		alertsApiClient.sendAlert(token, AlertKind.ACCOMPLISHMENT, summary, title, png, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				log.debug("Accomplishment alert failed: {}", message);
			}
		});
	}

	private void post(String token, String summary, String title)
	{
		alertsApiClient.sendAlert(token, AlertKind.ACCOMPLISHMENT, summary, title, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				log.debug("Accomplishment alert failed: {}", message);
			}
		});
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.google.common.base.Strings;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

/**
 * Shares Grandmaster/special quest completions to Discord. There's no dedicated quest-completion
 * event in the RuneLite API (no QuestCompleted class), and polling Quest.getState() on a timer proved
 * unreliable in practice - it must run on the client thread (calling it from a background poll threw
 * AssertionError every time), and quest state wasn't reliably settled by the exact moment
 * GameStateChanged reports LOGGED_IN either (baselining there still false-fired for every tracked
 * quest at once - confirmed live, twice). Detecting the login-completion chat message instead sidesteps
 * both problems: it only ever fires for a real completion happening live in this session, so there is
 * no "already-done" state to race against or baseline in the first place.
 */
@Slf4j
public class QuestMilestoneListener
{
	private static final Set<Quest> TRACKED_QUESTS = Set.of(
		Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE,
		Quest.DRAGON_SLAYER_II,
		Quest.MONKEY_MADNESS_II,
		Quest.SONG_OF_THE_ELVES,
		Quest.RECIPE_FOR_DISASTER,
		Quest.WHILE_GUTHIX_SLEEPS,
		Quest.THE_BLOOD_MOON_RISES
	);

	// Best-effort recalled wording, not confirmed against a live client - same caveat as
	// PetDropListener/OneTimeRewardListener (see concerns.json WRN-006). Tighten if it turns out wrong.
	private static final Pattern QUEST_COMPLETE_MESSAGE = Pattern.compile(
		"Congratulations, you have completed a quest", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final CatastrophicEventsConfig config;
	private final AlertsApiClient alertsApiClient;

	// Which tracked quests are already known finished, so the generic completion chat message (it
	// doesn't name the quest) only ever reports whichever one(s) are newly FINISHED and not already in
	// this set - never anything the player already had done coming into this session. Seeded once,
	// a few ticks after login rather than immediately on it, to give quest state (which lagged behind
	// the rest of login by a tick or more - also confirmed live) time to fully settle; only ever used to
	// suppress already-known completions, never as the trigger to alert, so being a little late seeding
	// it is harmless - nothing can complete a Grandmaster quest in the first few ticks after logging in.
	private final Set<Quest> knownFinished = new HashSet<>();
	private boolean baselineSeedPending;

	@Inject
	public QuestMilestoneListener(Client client, CatastrophicEventsConfig config, AlertsApiClient alertsApiClient)
	{
		this.client = client;
		this.config = config;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			baselineSeedPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!baselineSeedPending)
		{
			return;
		}

		baselineSeedPending = false;
		for (Quest quest : TRACKED_QUESTS)
		{
			if (quest.getState(client) == QuestState.FINISHED)
			{
				knownFinished.add(quest);
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.accomplishmentSharingEnabled())
		{
			return;
		}

		String message = event.getMessage();
		if (Strings.isNullOrEmpty(message) || !QUEST_COMPLETE_MESSAGE.matcher(message).find())
		{
			return;
		}

		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		for (Quest quest : TRACKED_QUESTS)
		{
			if (knownFinished.contains(quest) || quest.getState(client) != QuestState.FINISHED)
			{
				continue;
			}

			knownFinished.add(quest);
			String questName = quest.getName();
			alertsApiClient.sendAlert(token, AlertKind.ACCOMPLISHMENT, String.format("completed %s", questName), questName,
				new ApiCallback<Void>()
				{
					@Override
					public void onSuccess(Void result)
					{
					}

					@Override
					public void onError(ApiErrorType type, String errorMessage)
					{
						log.debug("Quest accomplishment alert failed: {}", errorMessage);
					}
				});
		}
	}
}

package com.catastrophic.events.alerts;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.api.AlertsApiClient;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.google.common.base.Strings;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Shares loot to Discord in two independent ways: any single non-stackable drop worth 1.5m gp or
 * more (LOOT), and a fixed allowlist of mega-rare/high-value one-off drops regardless of value
 * (ACCOMPLISHMENT) - an item can trigger both. Listens on all three of RuneLite's loot sources:
 * NpcLootReceived/PlayerLootReceived (direct NPC/PK kills) and LootReceived filtered to
 * EVENT/PICKPOCKET (chest/reward-interface/minigame content - e.g. Doom of Mokhaiotl - that never
 * fires the first two; NPC/PLAYER-typed LootReceived is skipped since those would duplicate the
 * other two sources).
 */
@Slf4j
public class LootAlertListener
{
	private static final long VALUE_THRESHOLD_GP = 1_500_000L;

	private static final Set<Integer> TRACKED_ACCOMPLISHMENT_ITEM_IDS = Set.of(
		ItemID.TWISTED_BOW,
		ItemID.SCYTHE_OF_VITUR,
		ItemID.TUMEKENS_SHADOW,
		ItemID.ANCIENT_BLOOD_ORNAMENT_KIT,
		ItemID.PURIFYING_SIGIL
	);

	private final CatastrophicEventsConfig config;
	private final ItemManager itemManager;
	private final ScreenshotCapture screenshotCapture;
	private final AlertsApiClient alertsApiClient;

	@Inject
	public LootAlertListener(CatastrophicEventsConfig config, ItemManager itemManager,
		ScreenshotCapture screenshotCapture, AlertsApiClient alertsApiClient)
	{
		this.config = config;
		this.itemManager = itemManager;
		this.screenshotCapture = screenshotCapture;
		this.alertsApiClient = alertsApiClient;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		handleLoot(event.getItems(), npc.getName() == null ? "an NPC" : npc.getName());
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		Player player = event.getPlayer();
		handleLoot(event.getItems(), player.getName() == null ? "a player" : player.getName());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() != LootRecordType.EVENT && event.getType() != LootRecordType.PICKPOCKET)
		{
			return;
		}

		handleLoot(event.getItems(), event.getName());
	}

	private void handleLoot(Iterable<ItemStack> items, String source)
	{
		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		for (ItemStack item : items)
		{
			ItemComposition composition = itemManager.getItemComposition(item.getId());

			if (config.lootSharingEnabled() && !composition.isStackable())
			{
				long totalValue = (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
				if (totalValue >= VALUE_THRESHOLD_GP)
				{
					String summary = String.format("Received %s (x%d) worth %,d gp from %s",
						composition.getName(), item.getQuantity(), totalValue, source);
					sendLootAlert(token, summary);
				}
			}

			if (config.accomplishmentSharingEnabled() && TRACKED_ACCOMPLISHMENT_ITEM_IDS.contains(item.getId()))
			{
				String summary = String.format("received %s from %s", composition.getName(), source);
				sendAccomplishmentAlert(token, composition.getName(), summary);
			}
		}
	}

	private void sendLootAlert(String token, String summary)
	{
		screenshotCapture.capture(png -> alertsApiClient.sendAlert(token, AlertKind.LOOT, summary, png, new ApiCallback<Void>()
		{
			@Override
			public void onSuccess(Void result)
			{
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				log.debug("Loot alert failed: {}", message);
			}
		}));
	}

	private void sendAccomplishmentAlert(String token, String title, String summary)
	{
		screenshotCapture.capture(png -> alertsApiClient.sendAlert(token, AlertKind.ACCOMPLISHMENT, summary, title, png,
			new ApiCallback<Void>()
			{
				@Override
				public void onSuccess(Void result)
				{
				}

				@Override
				public void onError(ApiErrorType type, String message)
				{
					log.debug("Accomplishment loot alert failed: {}", message);
				}
			}));
	}
}

package com.catastrophic.events.alerts;

/** Matches the `kind` field expected by catabot's POST /alerts endpoint. */
public enum AlertKind
{
	LOOT("loot"),
	DEATH("death"),
	COFFER("coffer"),
	ACCOMPLISHMENT("accomplishment"),
	PET("pet");

	private final String wireValue;

	AlertKind(String wireValue)
	{
		this.wireValue = wireValue;
	}

	public String wireValue()
	{
		return wireValue;
	}
}

package com.catastrophic.events;

import com.catastrophic.events.alerts.CofferAlertListener;
import com.catastrophic.events.alerts.DeathAlertListener;
import com.catastrophic.events.alerts.LootAlertListener;
import com.catastrophic.events.alerts.OneTimeRewardListener;
import com.catastrophic.events.alerts.PetDropListener;
import com.catastrophic.events.alerts.QuestMilestoneListener;
import com.catastrophic.events.alerts.SkillMilestoneListener;
import com.catastrophic.events.api.ApiCallback;
import com.catastrophic.events.api.ApiErrorType;
import com.catastrophic.events.api.EventsApiClient;
import com.catastrophic.events.api.dto.EventDto;
import com.catastrophic.events.api.dto.EventsResponse;
import com.catastrophic.events.api.dto.SignupResponse;
import com.catastrophic.events.ui.CatastrophicEventsPanel;
import com.google.common.base.Strings;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.swing.JButton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Catastrophic Events",
	description = "Browse upcoming clan events, sign up with one click, and get private reminders before they start",
	tags = {"events", "clan", "discord", "signup", "reminder"}
)
public class CatastrophicEventsPlugin extends Plugin
{
	private static final int POLL_INTERVAL_SECONDS = 45;
	private static final int[] REMINDER_MILESTONES_MINUTES = {180, 60, 5};
	public static final String DISCORD_GUILD_ID = "703371593937584198";
	private static final String CONFIG_GROUP = "catastrophicevents";
	private static final String DEATH_MESSAGE_NAME_TOKEN_MIGRATED_KEY = "deathMessageNameTokenMigratedV2";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private CatastrophicEventsConfig config;

	@Inject
	private EventsApiClient apiClient;

	@Inject
	private ConfigManager configManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private LootAlertListener lootAlertListener;

	@Inject
	private DeathAlertListener deathAlertListener;

	@Inject
	private CofferAlertListener cofferAlertListener;

	@Inject
	private SkillMilestoneListener skillMilestoneListener;

	@Inject
	private QuestMilestoneListener questMilestoneListener;

	@Inject
	private PetDropListener petDropListener;

	@Inject
	private OneTimeRewardListener oneTimeRewardListener;

	private CatastrophicEventsPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> pollTask;

	// dedupe key: "eventId:milestone" - a reminder fires once per event+milestone, not every poll cycle
	private final Set<String> remindersShown = ConcurrentHashMap.newKeySet();

	// Fires the "here's what you're signed up for" summary once per client session, on the first successful poll.
	private final AtomicBoolean announcedThisSession = new AtomicBoolean(false);

	@Provides
	CatastrophicEventsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CatastrophicEventsConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateDeathMessageNameToken();

		panel = new CatastrophicEventsPanel(this::onJoinClicked, configManager, config, this::pollEvents);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Catastrophic Events")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		eventBus.register(lootAlertListener);
		eventBus.register(deathAlertListener);
		eventBus.register(cofferAlertListener);
		eventBus.register(skillMilestoneListener);
		eventBus.register(questMilestoneListener);
		eventBus.register(petDropListener);
		eventBus.register(oneTimeRewardListener);

		remindersShown.clear();
		announcedThisSession.set(false);
		pollTask = executor.scheduleWithFixedDelay(this::pollEvents, 0, POLL_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		if (pollTask != null)
		{
			pollTask.cancel(true);
			pollTask = null;
		}
		eventBus.unregister(lootAlertListener);
		eventBus.unregister(deathAlertListener);
		eventBus.unregister(cofferAlertListener);
		eventBus.unregister(skillMilestoneListener);
		eventBus.unregister(questMilestoneListener);
		eventBus.unregister(petDropListener);
		eventBus.unregister(oneTimeRewardListener);
		clientToolbar.removeNavigation(navButton);
		panel.destroy();
	}

	/**
	 * One-time migration: players who already had a custom death message before the $name token existed
	 * get it prepended automatically (e.g. "is a silly goose" -> "$name is a silly goose"), so it reads as
	 * a natural sentence and they can reposition it in the config panel if they want.
	 */
	private void migrateDeathMessageNameToken()
	{
		if (!Strings.isNullOrEmpty(configManager.getConfiguration(CONFIG_GROUP, DEATH_MESSAGE_NAME_TOKEN_MIGRATED_KEY)))
		{
			return;
		}

		String message = config.deathMessage();
		if (!Strings.isNullOrEmpty(message))
		{
			String withoutToken = message.replace(DeathAlertListener.NAME_TOKEN, "").trim();
			String migrated = Strings.isNullOrEmpty(withoutToken)
				? DeathAlertListener.NAME_TOKEN
				: DeathAlertListener.NAME_TOKEN + " " + withoutToken;
			configManager.setConfiguration(CONFIG_GROUP, "deathMessage", migrated);
		}

		configManager.setConfiguration(CONFIG_GROUP, DEATH_MESSAGE_NAME_TOKEN_MIGRATED_KEY, "true");
	}

	private void pollEvents()
	{
		// scheduleWithFixedDelay permanently kills this recurring task the moment any single
		// invocation throws - so nothing below may be allowed to escape uncaught, or the panel
		// gets stuck on its last state (typically the NOT_LINKED default) for the rest of the
		// client session even with a perfectly valid token. Catches Throwable, not just Exception -
		// confirmed live that RuneLite's own API can throw AssertionError (a client-thread violation),
		// which Exception alone does not catch.
		try
		{
			pollEventsUnsafe();
		}
		catch (Throwable t)
		{
			log.warn("Catastrophic Events poll cycle failed, will retry next cycle", t);
		}
	}

	private void pollEventsUnsafe()
	{
		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			SwingUtilities.invokeLater(panel::showNotLinked);
			return;
		}

		apiClient.fetchEvents(token, new ApiCallback<EventsResponse>()
		{
			@Override
			public void onSuccess(EventsResponse result)
			{
				List<EventDto> events = result.getEvents() == null ? Collections.emptyList() : result.getEvents();
				SwingUtilities.invokeLater(() -> panel.showEvents(events));
				checkReminderMilestones(events);
				if (announcedThisSession.compareAndSet(false, true))
				{
					announceSignedUpEvents(events);
				}
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				if (type == ApiErrorType.UNAUTHORIZED)
				{
					SwingUtilities.invokeLater(panel::showNotLinked);
				}
				else
				{
					log.debug("Failed to fetch Catastrophic Events: {}", message);
					SwingUtilities.invokeLater(panel::showConnectionError);
				}
			}
		});
	}

	private void onJoinClicked(EventDto event, JButton joinButton)
	{
		String token = config.token();
		if (Strings.isNullOrEmpty(token))
		{
			return;
		}

		joinButton.setEnabled(false);
		joinButton.setText("Joining...");

		apiClient.signup(token, event.getId(), new ApiCallback<SignupResponse>()
		{
			@Override
			public void onSuccess(SignupResponse result)
			{
				SwingUtilities.invokeLater(() ->
				{
					joinButton.setText("Signed Up ✓");
					joinButton.setEnabled(false);
				});
			}

			@Override
			public void onError(ApiErrorType type, String message)
			{
				log.debug("Signup for event {} failed: {}", event.getId(), message);
				SwingUtilities.invokeLater(() ->
				{
					joinButton.setText("Join");
					joinButton.setEnabled(true);
				});
			}
		});
	}

	private void checkReminderMilestones(List<EventDto> events)
	{
		if (!config.eventRemindersEnabled())
		{
			return;
		}

		for (EventDto event : events)
		{
			if (!event.isSignedUp())
			{
				continue;
			}

			long minutesUntil;
			try
			{
				minutesUntil = event.minutesUntilStart();
			}
			catch (Exception e)
			{
				continue;
			}

			if (minutesUntil < 0)
			{
				continue;
			}

			for (int milestone : REMINDER_MILESTONES_MINUTES)
			{
				String key = event.getId() + ":" + milestone;
				if (minutesUntil <= milestone && remindersShown.add(key))
				{
					sendReminder(event, milestone);
				}
			}
		}
	}

	private void sendReminder(EventDto event, int milestoneMinutes)
	{
		String text = milestoneMinutes >= 60
			? String.format("%s starts in %d hour(s)", event.getTitle(), milestoneMinutes / 60)
			: String.format("%s starts in %d min", event.getTitle(), milestoneMinutes);
		sendClientMessage(text);
	}

	/** One-time "here's what you're signed up for" summary, one chat message per event, fired once per session. */
	private void announceSignedUpEvents(List<EventDto> events)
	{
		if (!config.eventRemindersEnabled())
		{
			return;
		}

		for (EventDto event : events)
		{
			if (!event.isSignedUp())
			{
				continue;
			}

			long minutesUntil;
			try
			{
				minutesUntil = event.minutesUntilStart();
			}
			catch (Exception e)
			{
				continue;
			}

			if (minutesUntil < 0)
			{
				continue;
			}

			sendClientMessage(String.format("%s starts in %s", event.getTitle(), formatDuration(minutesUntil)));
		}
	}

	private static String formatDuration(long minutes)
	{
		if (minutes < 60)
		{
			return minutes + " min";
		}
		long hours = minutes / 60;
		if (hours < 24)
		{
			return hours + "h " + (minutes % 60) + "m";
		}
		return (hours / 24) + "d " + (hours % 24) + "h";
	}

	private void sendClientMessage(String text)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.sender("Catastrophic Events")
			.runeLiteFormattedMessage("[Catastrophic Events] : " + text)
			.build());
	}
}

package com.catastrophic.events.ui;

import java.awt.Color;
import java.awt.Font;
import javax.swing.JTextArea;

/**
 * A label that actually reflows to whatever width the layout gives it, instead of a JLabel +
 * hardcoded HTML pixel width - which fights FlatLaf's auto-ellipsis and clips mid-word once the
 * real layout width doesn't match the guessed CSS width.
 */
class WrappingLabel extends JTextArea
{
	WrappingLabel(String text, Font font, Color color)
	{
		super(text);
		setEditable(false);
		setFocusable(false);
		setOpaque(false);
		setLineWrap(true);
		setWrapStyleWord(true);
		setBorder(null);
		setMargin(new java.awt.Insets(0, 0, 0, 0));
		setFont(font);
		setForeground(color);
	}
}

package com.catastrophic.events.ui;

import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import javax.swing.Icon;

/** Small hand-drawn glyphs for info rows (clock, world, people) - not font glyphs, so coverage is never a gamble. */
class RowIcon implements Icon
{
	enum Type
	{
		CLOCK, WORLD, PEOPLE
	}

	private final Type type;
	private final int size;

	RowIcon(Type type, int size)
	{
		this.type = type;
		this.size = size;
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(CatastrophicTheme.TEXT_DIM);
		g2.setStroke(new java.awt.BasicStroke(1.3f));

		switch (type)
		{
			case CLOCK:
				paintClock(g2, x, y);
				break;
			case WORLD:
				paintWorld(g2, x, y);
				break;
			case PEOPLE:
				paintPeople(g2, x, y);
				break;
		}

		g2.dispose();
	}

	private void paintClock(Graphics2D g2, int x, int y)
	{
		float inset = size * 0.1f;
		g2.draw(new Ellipse2D.Float(x + inset, y + inset, size - 2 * inset, size - 2 * inset));
		float cx = x + size / 2f;
		float cy = y + size / 2f;
		g2.draw(new Line2D.Float(cx, cy, cx, y + size * 0.28f));
		g2.draw(new Line2D.Float(cx, cy, x + size * 0.66f, cy));
	}

	private void paintWorld(Graphics2D g2, int x, int y)
	{
		float inset = size * 0.1f;
		g2.draw(new Ellipse2D.Float(x + inset, y + inset, size - 2 * inset, size - 2 * inset));
		g2.draw(new Ellipse2D.Float(x + size * 0.32f, y + inset, size * 0.36f, size - 2 * inset));
		g2.draw(new Line2D.Float(x + inset, y + size / 2f, x + size - inset, y + size / 2f));
	}

	private void paintPeople(Graphics2D g2, int x, int y)
	{
		float headSize = size * 0.34f;
		g2.draw(new Ellipse2D.Float(x + size * 0.08f, y + size * 0.12f, headSize, headSize));
		g2.draw(new Ellipse2D.Float(x + size * 0.42f, y + size * 0.3f, headSize, headSize));
	}

	@Override
	public int getIconWidth()
	{
		return size;
	}

	@Override
	public int getIconHeight()
	{
		return size;
	}
}

package com.catastrophic.events.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;

/** A JPanel that paints itself as a subtly-gradiented rounded rectangle with an optional border. */
class RoundedPanel extends JPanel
{
	private final int arc;
	private final Color fillTop;
	private final Color fillBottom;
	private final Color border;
	private final Color borderHover;

	private boolean hovered;

	RoundedPanel(int arc, Color fill, Color border)
	{
		this(arc, fill, border, false);
	}

	RoundedPanel(int arc, Color fill, Color border, boolean hoverable)
	{
		this.arc = arc;
		this.fillTop = lighten(fill, 10);
		this.fillBottom = fill;
		this.border = border;
		this.borderHover = border == null ? null : lighten(border, 45);
		setOpaque(false);

		if (hoverable && border != null)
		{
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					hovered = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					// Moving onto a child (button, label) still fires exited on the parent -
					// only actually clear hover once the cursor has left this panel's bounds.
					if (!contains(e.getPoint()))
					{
						hovered = false;
						repaint();
					}
				}
			});
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setPaint(new GradientPaint(0, 0, fillTop, 0, getHeight(), fillBottom));
		g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
		if (border != null)
		{
			g2.setColor(hovered ? borderHover : border);
			g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
		}
		g2.dispose();
		super.paintComponent(g);
	}

	private static Color lighten(Color c, int delta)
	{
		return new Color(
			Math.min(255, c.getRed() + delta),
			Math.min(255, c.getGreen() + delta),
			Math.min(255, c.getBlue() + delta));
	}
}

