import javax.swing.JTextField;
import net.runelite.client.config.ConfigManager;

/** Inline "Event Setup" form opened from the gear icon, writes straight to ConfigManager on Save. */
class SettingsView extends JPanel
{
	private static final String CONFIG_GROUP = "catastrophicevents";

	SettingsView(ConfigManager configManager, Runnable onSaved)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));

		JTextField tokenField = field(configManager.getConfiguration(CONFIG_GROUP, "token"));

		add(fieldRow("Plugin token", tokenField));
		add(Box.createRigidArea(new Dimension(0, 6)));

		StyledButton saveButton = StyledButton.pill("Save", CatastrophicTheme.GOLD, CatastrophicTheme.BACKGROUND);
		saveButton.setFont(CatastrophicTheme.boldFont());
		saveButton.setAlignmentX(LEFT_ALIGNMENT);
		saveButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		saveButton.addActionListener(e ->
		{
			configManager.setConfiguration(CONFIG_GROUP, "token", tokenField.getText().trim());
			onSaved.run();
		});
		add(saveButton);
	}

	private static JPanel fieldRow(String label, JTextField field)
	{
		JPanel row = new JPanel();
		row.setOpaque(false);
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

		JLabel labelComponent = new JLabel(label);
		labelComponent.setFont(CatastrophicTheme.smallFont());
		labelComponent.setForeground(CatastrophicTheme.TEXT_DIM);
		labelComponent.setAlignmentX(LEFT_ALIGNMENT);
		row.add(labelComponent);

		field.setAlignmentX(LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		row.add(field);
		return row;
	}

	private static JTextField field(String initialValue)
	{
		JTextField field = new JTextField(initialValue == null ? "" : initialValue);
		// Pre-fills with whatever's already saved (e.g. re-opening after a bad token) - select it
		// so a paste replaces it outright instead of inserting at the caret and corrupting it.
		field.selectAll();
		field.setFont(CatastrophicTheme.smallFont().deriveFont(Font.PLAIN));
		field.setBackground(CatastrophicTheme.CARD_BACKGROUND);
		field.setForeground(CatastrophicTheme.TEXT);
		field.setCaretColor(CatastrophicTheme.TEXT);
		field.setBorder(BorderFactory.createLineBorder(CatastrophicTheme.CARD_BORDER));
		field.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusGained(FocusEvent e)
			{
				field.setBorder(BorderFactory.createLineBorder(CatastrophicTheme.GOLD));
			}

			@Override
			public void focusLost(FocusEvent e)
			{
				field.setBorder(BorderFactory.createLineBorder(CatastrophicTheme.CARD_BORDER));
			}
		});
		return field;
	}
}

package com.catastrophic.events.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JButton;

/**
 * A small circular button for the footer icon row, showing either a text glyph (drawn with a
 * plain system font, not RuneLite's bitmap RuneScape font, so coverage is never a gamble) or a
 * bundled image (e.g. an official brand mark).
 */
class CircleIconButton extends JButton
{
	private static final int DIAMETER = 40;

	private final Color fill;
	private final String glyph;
	private final BufferedImage image;

	CircleIconButton(String glyph, Color fill, String tooltip)
	{
		this(glyph, null, fill, tooltip);
	}

	CircleIconButton(BufferedImage image, Color fill, String tooltip)
	{
		this(null, image, fill, tooltip);
	}

	private CircleIconButton(String glyph, BufferedImage image, Color fill, String tooltip)
	{
		this.glyph = glyph;
		this.image = image;
		this.fill = fill;
		setToolTipText(tooltip);
		setPreferredSize(new Dimension(DIAMETER, DIAMETER));
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		Color bg = getModel().isPressed() ? fill.darker() : getModel().isRollover() ? fill.brighter() : fill;
		g2.setColor(bg);
		g2.fill(new Ellipse2D.Float(0, 0, DIAMETER, DIAMETER));
		g2.setColor(CatastrophicTheme.CARD_BORDER);
		g2.draw(new Ellipse2D.Float(0, 0, DIAMETER - 1, DIAMETER - 1));

		if (image != null)
		{
			int w = image.getWidth();
			int h = image.getHeight();
			g2.drawImage(image, (DIAMETER - w) / 2, (DIAMETER - h) / 2, w, h, null);
		}
		else
		{
			g2.setColor(CatastrophicTheme.TEXT);
			g2.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 18));
			int textWidth = g2.getFontMetrics().stringWidth(glyph);
			int textHeight = g2.getFontMetrics().getAscent();
			g2.drawString(glyph, (DIAMETER - textWidth) / 2f, (DIAMETER + textHeight) / 2f - 3);
		}

		g2.dispose();
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(DIAMETER, DIAMETER);
	}
}

package com.catastrophic.events.ui;

import com.catastrophic.events.CatastrophicEventsPlugin;
import com.catastrophic.events.api.dto.EventDto;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.time.OffsetDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSeparator;
import net.runelite.client.util.LinkBrowser;

/** The expanded "featured" event card - the soonest joined event on the My Events tab. */
class EventHeroCard extends RoundedPanel
{
	private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("h:mm a z");
	private static final int STARTING_SOON_THRESHOLD_MINUTES = 60;

	EventHeroCard(EventDto event, Consumer<JButton> onJoinClicked)
	{
		super(14, CatastrophicTheme.CARD_BACKGROUND, CatastrophicTheme.CARD_BORDER);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(BorderFactory.createEmptyBorder(
			CatastrophicTheme.SPACE_LG, CatastrophicTheme.SPACE_LG, CatastrophicTheme.SPACE_LG, CatastrophicTheme.SPACE_LG));

		add(header(event));
		add(gap(CatastrophicTheme.SPACE_MD));
		add(countdown(event));
		add(gap(CatastrophicTheme.SPACE_XS));
		add(separator());
		add(gap(CatastrophicTheme.SPACE_XS));
		add(infoRow(RowIcon.Type.CLOCK, "Time", formatTime(event)));
		add(infoRow(RowIcon.Type.WORLD, "World", worldText(event)));
		add(gap(CatastrophicTheme.SPACE_XS));
		add(separator());
		add(gap(CatastrophicTheme.SPACE_XS));
		add(infoRow(RowIcon.Type.PEOPLE, "Attendance", attendanceText(event)));
		add(featureRow("Auto check-in", "Coming soon", false));
		add(featureRow("Drop screenshots", "Coming soon", false));
		add(featureRow("Notifications", "Joined events only", true));
		add(gap(CatastrophicTheme.SPACE_MD));
		add(joinButtonRow(event, onJoinClicked));
		add(gap(CatastrophicTheme.SPACE_SM));
		add(discordVoiceRow(event));
	}

	private static Component gap(int height)
	{
		return Box.createRigidArea(new Dimension(0, height));
	}

	private JPanel header(EventDto event)
	{
		JPanel row = new JPanel(new BorderLayout(CatastrophicTheme.SPACE_MD, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(new JLabel(new AvatarIcon(event.getTitle(), 64)), BorderLayout.WEST);

		JPanel titleCol = new JPanel();
		titleCol.setOpaque(false);
		titleCol.setLayout(new BoxLayout(titleCol, BoxLayout.Y_AXIS));

		WrappingLabel title = new WrappingLabel(event.getTitle(), CatastrophicTheme.titleFont(), CatastrophicTheme.TEXT);
		title.setSize(new Dimension(110, Short.MAX_VALUE));
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		titleCol.add(title);

		Long minutesUntil = safeMinutesUntilStart(event);
		if (minutesUntil != null && minutesUntil >= 0 && minutesUntil <= STARTING_SOON_THRESHOLD_MINUTES)
		{
			PillBadge badge = new PillBadge("STARTING SOON", CatastrophicTheme.GREEN_BADGE_BG, CatastrophicTheme.GREEN);
			badge.setAlignmentX(Component.LEFT_ALIGNMENT);
			titleCol.add(gap(CatastrophicTheme.SPACE_XS));
			titleCol.add(badge);
		}

		row.add(titleCol, BorderLayout.CENTER);
		return row;
	}

	private JPanel countdown(EventDto event)
	{
		JPanel row = new JPanel(new BorderLayout(CatastrophicTheme.SPACE_XS, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel icon = new JLabel(new RowIcon(RowIcon.Type.CLOCK, 20));
		row.add(icon, BorderLayout.WEST);

		WrappingLabel text = new WrappingLabel(countdownText(event), CatastrophicTheme.heroCountdownFont(), CatastrophicTheme.GOLD);
		text.setSize(new Dimension(150, Short.MAX_VALUE));
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	private JPanel joinButtonRow(EventDto event, Consumer<JButton> onJoinClicked)
	{
		boolean signedUp = event.isSignedUp();
		StyledButton joinButton = signedUp
			? StyledButton.outlined("Joined ✓", CatastrophicTheme.GREEN, CatastrophicTheme.GREEN, 8)
			: StyledButton.pill("Join", CatastrophicTheme.GOLD, CatastrophicTheme.BACKGROUND);
		joinButton.setEnabled(!signedUp);
		joinButton.setFont(CatastrophicTheme.boldFont().deriveFont(14f));
		joinButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		joinButton.setMinimumSize(new Dimension(10, 38));
		joinButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));
		joinButton.addActionListener(e -> onJoinClicked.accept(joinButton));

		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setOpaque(false);
		wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrap.add(joinButton, BorderLayout.CENTER);
		return wrap;
	}

	private JPanel discordVoiceRow(EventDto event)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(CatastrophicTheme.SPACE_SM, 0, CatastrophicTheme.SPACE_SM, 0));

		JLabel labelComponent = new JLabel("Discord Voice");
		labelComponent.setFont(CatastrophicTheme.smallFont());
		labelComponent.setForeground(CatastrophicTheme.TEXT_DIM);
		row.add(labelComponent, BorderLayout.WEST);

		String voiceChannelId = event.getDiscordVoiceChannelId();
		boolean canJoin = voiceChannelId != null && !voiceChannelId.isEmpty();

		if (canJoin)
		{
			StyledButton joinVc = StyledButton.outlined("Join VC", CatastrophicTheme.DISCORD_BLURPLE,
				CatastrophicTheme.DISCORD_BLURPLE, 999);
			joinVc.addActionListener(e -> openVoiceChannel(voiceChannelId));
			row.add(joinVc, BorderLayout.EAST);
		}
		else
		{
			JLabel notSet = new JLabel("Not set");
			notSet.setFont(CatastrophicTheme.smallFont());
			notSet.setForeground(CatastrophicTheme.TEXT_DISABLED);
			row.add(notSet, BorderLayout.EAST);
		}

		return row;
	}

	private static void openVoiceChannel(String voiceChannelId)
	{
		LinkBrowser.browse("https://discord.com/channels/" + CatastrophicEventsPlugin.DISCORD_GUILD_ID + "/" + voiceChannelId);
	}

	private static String worldText(EventDto event)
	{
		Integer world = event.getWorld();
		return world == null ? "Not set by host yet" : "W" + world;
	}

	private static JPanel infoRow(RowIcon.Type icon, String label, String value)
	{
		return infoRow(icon, label, value, CatastrophicTheme.TEXT);
	}

	private static JPanel infoRow(RowIcon.Type icon, String label, String value, Color valueColor)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(CatastrophicTheme.SPACE_SM, 0, CatastrophicTheme.SPACE_SM, 0));

		JPanel labelWrap = new JPanel(new FlowLayout(FlowLayout.LEFT, CatastrophicTheme.SPACE_XS, 0));
		labelWrap.setOpaque(false);

		if (icon != null)
		{
			labelWrap.add(new JLabel(new RowIcon(icon, 13)));
		}

		JLabel labelComponent = new JLabel(label);
		labelComponent.setFont(CatastrophicTheme.smallFont());
		labelComponent.setForeground(CatastrophicTheme.TEXT_DIM);
		labelWrap.add(labelComponent);
		row.add(labelWrap, BorderLayout.WEST);

		JLabel valueComponent = new JLabel(value);
		valueComponent.setFont(CatastrophicTheme.smallFont());
		valueComponent.setForeground(valueColor);
		row.add(valueComponent, BorderLayout.EAST);
		return row;
	}

	private static JPanel featureRow(String label, String status, boolean available)
	{
		String display = available ? status + " ✓" : status;
		return infoRow(null, label, display, available ? CatastrophicTheme.GREEN : CatastrophicTheme.TEXT_DISABLED);
	}

	private static JSeparator separator()
	{
		JSeparator separator = new JSeparator();
		separator.setForeground(CatastrophicTheme.CARD_BORDER);
		separator.setBackground(CatastrophicTheme.CARD_BACKGROUND);
		separator.setAlignmentX(Component.LEFT_ALIGNMENT);
		separator.setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
		return separator;
	}

	private static String attendanceText(EventDto event)
	{
		EventDto.Attendance attendance = event.getAttendance();
		if (attendance == null)
		{
			return "unknown";
		}
		return attendance.getSignedUp() + " signed up · " + attendance.getPresent() + " present";
	}

	private static String countdownText(EventDto event)
	{
		Long minutes = safeMinutesUntilStart(event);
		if (minutes == null)
		{
			return "Start time unknown";
		}
		if (minutes < 0)
		{
			return "Already started";
		}
		if (minutes < 60)
		{
			return "Starts in " + minutes + "m";
		}
		long hours = minutes / 60;
		if (hours < 24)
		{
			return "Starts in " + hours + "h " + (minutes % 60) + "m";
		}
		return "Starts in " + (hours / 24) + "d " + (hours % 24) + "h";
	}

	private static Long safeMinutesUntilStart(EventDto event)
	{
		try
		{
			return event.minutesUntilStart();
		}
		catch (Exception e)
		{
			return null;
		}
	}

	private static String formatTime(EventDto event)
	{
		try
		{
			OffsetDateTime start = OffsetDateTime.parse(event.getStartAt());
			return TIME_FORMAT.format(start.atZoneSameInstant(java.time.ZoneId.systemDefault()));
		}
		catch (DateTimeParseException | NullPointerException e)
		{
			return "unknown";
		}
	}
}

package com.catastrophic.events.ui;

import com.catastrophic.events.api.dto.EventDto;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

class EventCompactRow extends RoundedPanel
{
	private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("h:mm a");
	private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("EEE M/d");

	EventCompactRow(EventDto event, Consumer<JButton> onJoinClicked)
	{
		super(10, CatastrophicTheme.CARD_BACKGROUND, CatastrophicTheme.CARD_BORDER, true);
		setLayout(new BorderLayout(CatastrophicTheme.SPACE_SM, 0));
		setBorder(BorderFactory.createEmptyBorder(
			CatastrophicTheme.SPACE_MD, CatastrophicTheme.SPACE_MD, CatastrophicTheme.SPACE_MD, CatastrophicTheme.SPACE_SM));

		JLabel avatar = new JLabel(new AvatarIcon(event.getTitle(), 40));
		add(avatar, BorderLayout.WEST);

		WrappingLabel title = new WrappingLabel(event.getTitle(), CatastrophicTheme.boldFont(), CatastrophicTheme.TEXT);
		title.setSize(new Dimension(70, Short.MAX_VALUE));

		WrappingLabel subtitle = new WrappingLabel(subtitleText(event), CatastrophicTheme.smallFont(), CatastrophicTheme.TEXT_DIM);
		subtitle.setSize(new Dimension(70, Short.MAX_VALUE));
		subtitle.setBorder(BorderFactory.createEmptyBorder(CatastrophicTheme.SPACE_XS, 0, 0, 0));

		JPanel textPanel = new JPanel();
		textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
		textPanel.setOpaque(false);
		textPanel.add(title);
		textPanel.add(subtitle);
		add(textPanel, BorderLayout.CENTER);

		JPanel buttonWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		buttonWrap.setOpaque(false);
		boolean signedUp = event.isSignedUp();
		StyledButton joinButton = signedUp
			? StyledButton.outlined("Joined", CatastrophicTheme.GREEN, CatastrophicTheme.GREEN, 999)
			: StyledButton.pill("Join", CatastrophicTheme.GOLD, CatastrophicTheme.BACKGROUND);
		joinButton.setEnabled(!signedUp);
		joinButton.addActionListener(e -> onJoinClicked.accept(joinButton));
		buttonWrap.add(joinButton);
		add(buttonWrap, BorderLayout.EAST);
	}

	private static String subtitleText(EventDto event)
	{
		// event.getHostDiscordId() is now populated by the API, but it's a raw Discord ID with
		// no username to display - prefix it here once the API can resolve/include a display name.
		return formatTime(event);
	}

	private static String formatTime(EventDto event)
	{
		try
		{
			OffsetDateTime start = OffsetDateTime.parse(event.getStartAt());
			ZonedDateTime startLocal = start.atZoneSameInstant(ZoneId.systemDefault());
			return dayLabel(startLocal) + " · " + TIME_FORMAT.format(startLocal);
		}
		catch (DateTimeParseException | NullPointerException e)
		{
			return "time unknown";
		}
	}

	private static String dayLabel(ZonedDateTime startLocal)
	{
		LocalDate today = LocalDate.now(startLocal.getZone());
		LocalDate startDate = startLocal.toLocalDate();
		if (startDate.equals(today))
		{
			return "Today";
		}
		if (startDate.equals(today.plusDays(1)))
		{
			return "Tomorrow";
		}
		return DATE_FORMAT.format(startLocal);
	}
}

package com.catastrophic.events.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import javax.swing.JButton;

/** Fully custom-painted button (no default L&F chrome) so buttons can be true rounded pills, not tinted rectangles. */
class StyledButton extends JButton
{
	private static final int PILL = -1;

	private final Color fill;
	private final Color fillHover;
	private final Color fillPressed;
	private final Color outline;
	private final int arc;

	static StyledButton pill(String text, Color fill, Color textColor)
	{
		return new StyledButton(text, fill, textColor, PILL, null);
	}

	static StyledButton outlined(String text, Color textColor, Color outline, int arc)
	{
		return new StyledButton(text, CatastrophicTheme.CARD_BACKGROUND, textColor, arc, outline);
	}

	StyledButton(String text, Color fill, Color textColor, int arc, Color outline)
	{
		super(text);
		this.fill = fill;
		// Brightening an already-bright fill (e.g. the gold pill buttons) barely reads as feedback,
		// so bright fills darken on hover/press instead - whichever direction actually shows.
		int direction = luminance(fill) > 140 ? -1 : 1;
		this.fillHover = brighten(fill, direction * 24);
		this.fillPressed = brighten(fill, direction * 44);
		this.outline = outline;
		this.arc = arc;

		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setForeground(textColor);
		setFont(CatastrophicTheme.smallFont());
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		// Generous default padding so text never gets tight - callers only need setPreferredSize for something unusual.
		setMargin(new Insets(6, 16, 6, 16));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		Color bg = !isEnabled() ? CatastrophicTheme.CARD_BACKGROUND
			: getModel().isPressed() ? fillPressed
			: getModel().isRollover() ? fillHover
			: fill;
		int cornerArc = arc == PILL ? getHeight() : arc;

		g2.setColor(bg);
		g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, cornerArc, cornerArc);

		if (outline != null)
		{
			g2.setColor(isEnabled() ? outline : CatastrophicTheme.CARD_BORDER);
			g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, cornerArc, cornerArc);
		}

		g2.dispose();
		super.paintComponent(g);
	}

	private static Color brighten(Color c, int delta)
	{
		return new Color(
			clamp(c.getRed() + delta),
			clamp(c.getGreen() + delta),
			clamp(c.getBlue() + delta));
	}

	private static int clamp(int v)
	{
		return Math.max(0, Math.min(255, v));
	}

	private static int luminance(Color c)
	{
		return (int) (0.299 * c.getRed() + 0.587 * c.getGreen() + 0.114 * c.getBlue());
	}
}

package com.catastrophic.events.ui;

import com.catastrophic.events.CatastrophicEventsConfig;
import com.catastrophic.events.CatastrophicEventsPlugin;
import com.catastrophic.events.api.dto.EventDto;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;

public class CatastrophicEventsPanel extends PluginPanel
{
	private enum Tab
	{
		ALL, MINE
	}

	private enum State
	{
		NOT_LINKED, CONNECTION_ERROR, EVENTS
	}

	private final BiConsumer<EventDto, JButton> joinHandler;
	private final ConfigManager configManager;
	private final CatastrophicEventsConfig config;
	private final Runnable onSettingsSaved;

	private final JPanel body = new JPanel();
	private final javax.swing.Timer ticker;

	private Tab activeTab = Tab.ALL;
	private State state = State.NOT_LINKED;
	private List<EventDto> events = List.of();
	private boolean showingSettings = false;

	public CatastrophicEventsPanel(BiConsumer<EventDto, JButton> joinHandler, ConfigManager configManager,
		CatastrophicEventsConfig config, Runnable onSettingsSaved)
	{
		this.joinHandler = joinHandler;
		this.configManager = configManager;
		this.config = config;
		this.onSettingsSaved = onSettingsSaved;

		setLayout(new BorderLayout());
		setBackground(CatastrophicTheme.BACKGROUND);

		add(header(), BorderLayout.NORTH);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		add(body, BorderLayout.CENTER);

		render();

		// Re-renders countdown text between polls, purely local - no network call.
		ticker = new javax.swing.Timer(30_000, e ->
		{
			if (state == State.EVENTS && !showingSettings)
			{
				render();
			}
		});
		ticker.start();
	}

	/** Stops the local re-render ticker; call from the plugin's shutDown(). */
	public void destroy()
	{
		ticker.stop();
	}

	public void showNotLinked()
	{
		state = State.NOT_LINKED;
		render();
	}

	public void showConnectionError()
	{
		state = State.CONNECTION_ERROR;
		render();
	}

	public void showEvents(List<EventDto> events)
	{
		state = State.EVENTS;
		this.events = events;
		render();
	}

	private JPanel header()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setOpaque(false);
		header.setBorder(BorderFactory.createEmptyBorder(
			CatastrophicTheme.SPACE_MD, CatastrophicTheme.SPACE_XS, CatastrophicTheme.SPACE_MD, CatastrophicTheme.SPACE_XS));

		BufferedImage logoImage = ImageUtil.loadImageResource(com.catastrophic.events.CatastrophicEventsPlugin.class, "icon.png");
		JLabel logo = new JLabel(new ImageIcon(logoImage));
		logo.setAlignmentX(Component.CENTER_ALIGNMENT);
		header.add(logo);
		header.add(Box.createRigidArea(new Dimension(0, CatastrophicTheme.SPACE_XS)));

		JLabel title = new JLabel("Catastrophic Events");
		title.setFont(CatastrophicTheme.titleFont());
		title.setForeground(CatastrophicTheme.GOLD);
		title.setAlignmentX(Component.CENTER_ALIGNMENT);
		header.add(title);

		JLabel subtitle = new JLabel("Join boss mass events & claim drops");
		subtitle.setFont(CatastrophicTheme.smallFont());
		subtitle.setForeground(CatastrophicTheme.TEXT_DIM);
		subtitle.setAlignmentX(Component.CENTER_ALIGNMENT);
		header.add(subtitle);

		return header;
	}

	private void render()
	{
		body.removeAll();

		if (showingSettings)
		{
			body.add(sectionLabel("Event Setup"));
			body.add(new SettingsView(configManager, this::onSettingsSavedInternal));
		}
		else if (state == State.NOT_LINKED)
		{
			body.add(message("Not linked",
				"Run /link-plugin in Discord (with your RSN), then paste the token it DMs you here via Event Setup below."));
		}
		else if (state == State.CONNECTION_ERROR)
		{
			body.add(message("Can't reach server", "Retrying in the background..."));
		}
		else
		{
			body.add(tabBar());
			body.add(Box.createRigidArea(new Dimension(0, CatastrophicTheme.SPACE_SM)));
			body.add(activeTab == Tab.ALL ? allEventsView() : myEventsView());
		}

		body.add(Box.createRigidArea(new Dimension(0, CatastrophicTheme.SPACE_MD)));
		body.add(footer());

		revalidate();
		repaint();
	}

	private void onSettingsSavedInternal()
	{
		showingSettings = false;
		onSettingsSaved.run();
		render();
	}

	private JPanel tabBar()
	{
		JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(tabButton("All Events", Tab.ALL));
		row.add(tabButton("My Events", Tab.MINE));
		return row;
	}

	private StyledButton tabButton(String text, Tab tab)
	{
		boolean active = activeTab == tab;
		StyledButton button = StyledButton.outlined(text, active ? CatastrophicTheme.GOLD : CatastrophicTheme.TEXT_DIM,
			active ? CatastrophicTheme.GOLD : CatastrophicTheme.CARD_BORDER, 8);
		button.setFont(CatastrophicTheme.smallFont().deriveFont(active ? Font.BOLD : Font.PLAIN));
		button.addActionListener(e -> switchTab(tab));
		return button;
	}

	private void switchTab(Tab tab)
	{
		activeTab = tab;
		render();
	}

	private JPanel allEventsView()
	{
		JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setOpaque(false);
		column.setAlignmentX(Component.LEFT_ALIGNMENT);

		List<EventDto> sorted = sortedByStart(events);
		if (sorted.isEmpty())
		{
			column.add(message("No upcoming events", null));
			return column;
		}

		for (EventDto event : sorted)
		{
			EventCompactRow row = new EventCompactRow(event, button -> joinHandler.accept(event, button));
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			column.add(row);
			column.add(Box.createRigidArea(new Dimension(0, CatastrophicTheme.SPACE_SM)));
		}
		return column;
	}

	private JPanel myEventsView()
	{
		JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setOpaque(false);
		column.setAlignmentX(Component.LEFT_ALIGNMENT);

		List<EventDto> joined = sortedByStart(events).stream()
			.filter(EventDto::isSignedUp)
			.collect(Collectors.toList());

		if (joined.isEmpty())
		{
			column.add(message("No joined events", "Switch to All Events to find something to join."));
			return column;
		}

		EventDto featured = joined.get(0);
		EventHeroCard hero = new EventHeroCard(featured, button -> joinHandler.accept(featured, button));
		hero.setAlignmentX(Component.LEFT_ALIGNMENT);
		column.add(hero);

		for (int i = 1; i < joined.size(); i++)
		{
			EventDto event = joined.get(i);
			column.add(Box.createRigidArea(new Dimension(0, CatastrophicTheme.SPACE_SM)));
			EventCompactRow row = new EventCompactRow(event, button -> joinHandler.accept(event, button));
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			column.add(row);
		}
		return column;
	}

	private static List<EventDto> sortedByStart(List<EventDto> events)
	{
		List<EventDto> copy = new ArrayList<>(events);
		copy.sort(Comparator.comparing(EventDto::getStartAt, Comparator.nullsLast(Comparator.naturalOrder())));
		return copy;
	}

	private JPanel footer()
	{
		JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, CatastrophicTheme.SPACE_LG, CatastrophicTheme.SPACE_XS));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		BufferedImage discordIcon = ImageUtil.loadImageResource(com.catastrophic.events.CatastrophicEventsPlugin.class, "discord-icon.png");
		CircleIconButton discord = new CircleIconButton(discordIcon, CatastrophicTheme.DISCORD_BLURPLE, "Open Discord");
		discord.addActionListener(e -> openDiscordServer());
		row.add(discord);

		CircleIconButton settings = new CircleIconButton("⚙", CatastrophicTheme.CARD_BACKGROUND,
			showingSettings ? "Close Settings" : "Plugin Settings");
		settings.addActionListener(e -> toggleSettings());
		row.add(settings);

		return row;
	}

	private void toggleSettings()
	{
		showingSettings = !showingSettings;
		render();
	}

	private void openDiscordServer()
	{
		LinkBrowser.browse("https://discord.com/channels/" + CatastrophicEventsPlugin.DISCORD_GUILD_ID);
	}

	private static JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(CatastrophicTheme.boldFont());
		label.setForeground(CatastrophicTheme.GOLD);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		return label;
	}

	private static JPanel message(String title, String body)
	{
		JPanel wrapper = new JPanel();
		wrapper.setLayout(new GridLayout(body == null ? 1 : 2, 1, 0, 4));
		wrapper.setOpaque(false);
		wrapper.setBorder(BorderFactory.createEmptyBorder(12, 4, 12, 4));

		JLabel titleLabel = new JLabel(title);
		titleLabel.setForeground(CatastrophicTheme.TEXT);
		titleLabel.setFont(CatastrophicTheme.boldFont());
		titleLabel.setHorizontalAlignment(SwingConstants.CENTER);
		wrapper.add(titleLabel);

		if (body != null)
		{
			JLabel bodyLabel = new JLabel("<html><div style='text-align:center'>" + body + "</div></html>");
			bodyLabel.setForeground(CatastrophicTheme.TEXT_DIM);
			bodyLabel.setFont(CatastrophicTheme.smallFont());
			bodyLabel.setHorizontalAlignment(SwingConstants.CENTER);
			wrapper.add(bodyLabel);
		}

		return wrapper;
	}
}

